shots.setup:
const CFG = { x: -250, z: -1276, d: [0, 1], phi: 0.5, lookY: 105, lookY2: 110, fov: 48, camH: 1.8, cam0: [-690, 0, -1480], cam1: [-675, 0, -1482] };
g.stage(4); g.game.sky.ask(16, 'overcast', true);
const T = window.__storm.tornado; T.root.name = 'tornado'; T.root.traverse((o) => { o.name = 'tornado-' + (o.name || 'part'); }); for (const k of Object.keys(T)) { const o = T[k]; if (o && o.isObject3D) o.name = 'tornado-' + k; }
P.tw = { x: CFG.x, y: 5, z: CFG.z };
T.start(CFG.x, CFG.z); T.forced.dx = CFG.d[0]; T.forced.dz = CFG.d[1]; T.forced.phi = CFG.phi;
const gh = (x, z) => { g.teleport(x, z, 0); g.step(20); return g.game.player.y; };
const Y0 = gh(CFG.cam0[0], CFG.cam0[2]), Y1 = gh(CFG.cam1[0], CFG.cam1[2]);
g.teleport(CFG.x, CFG.z, 0);
const V3 = g.game.camera.position.constructor;
P.each = () => { const p = T.pos; if (p && (p.x || p.z)) { P.tw.x = p.x; P.tw.z = p.z; } };
P.rec = () => ({ tw: [P.tw.x, T.root.position.y, P.tw.z] });
const ease = (x) => x * x * (3 - 2 * x);
P.place = (cam, s) => { const a = CFG.cam0, b = CFG.cam1, u = ease(s); const pos = [0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * u); pos[1] = Y0 + (Y1 - Y0) * u + CFG.camH; g.game.view = { pos: new V3(pos[0], pos[1], pos[2]), target: new V3(P.tw.x, CFG.lookY + (CFG.lookY2 - CFG.lookY) * u, P.tw.z) }; g.game.camera.fov = CFG.fov; g.game.camera.updateProjectionMatrix(); };
